using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;
using Xunit;

namespace MyApp.Evals;

public class ChatEvals : IAsyncLifetime
{
    private DistributedApplicationTestingBuilder _appHost = null!;
    private DistributedApplication _app = null!;
    private IChatClient _chatClient = null!;
    private IChatClient _evaluatorClient = null!;
    private ReportingConfiguration _reportingConfig = null!;

    public async ValueTask InitializeAsync()
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.Services.GetRequiredService<IChatClient>();

        // Use the same chat client as the evaluator for quality metrics
        _evaluatorClient = _app.Services.GetRequiredService<IChatClient>();

        _reportingConfig = new ReportingConfiguration(
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ],
            chatClient: _evaluatorClient,
            reportStorageRootPath: Path.Combine(Directory.GetCurrentDirectory(), "eval-reports"));
    }

    public async ValueTask DisposeAsync()
    {
        await _app.StopAsync();
        await _appHost.DisposeAsync();
    }

    [Fact]
    public async Task Chat_responds_coherently_to_greeting()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_responds_coherently_to_greeting));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how are you today?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        Assert.NotNull(response.Message.Text);
        Assert.NotEmpty(response.Message.Text);
    }

    [Fact]
    public async Task Chat_answers_factual_question()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_answers_factual_question));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France? Answer in one word.")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        Assert.NotNull(response.Message.Text);
        Assert.Contains("Paris", response.Message.Text, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public async Task Chat_follows_system_prompt()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_follows_system_prompt));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant that always responds in exactly three words."),
            new(ChatRole.User, "How is the weather?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        Assert.NotNull(response.Message.Text);
    }
}

